 if(!profileState?.connected)return `<div class="real-source-inline"><div class="callout">ORACLE READ-ONLY · ${realEscape(profile.name)} · Press Connect in the profile form to verify credentials and enable bounded read-only requests. No persistent Oracle socket is held; each read opens and closes a bounded connection.</div></div>`;
