function realSourceCatalogPreviewMarkup(){const preview=realSourceUI.catalogPreview;if(!preview)return '';if(preview.loading)return `<div class="catalog-object-preview" role="status">Loading ${realEscape(preview.schema)}.${realEscape(preview.name)} structure…</div>`;if(preview.error)return `<div class="catalog-object-preview"><b>Could not load object structure</b><p>${realEscape(preview.error)}</p><button type="button" onclick="realSourcePreviewObject('${realEscape(preview.key)}')">Retry</button></div>`;const metadata=preview.metadata,columns=metadata?.columns||[],keys=metadata?.keys||[],foreign=metadata?.foreign_keys||[],sample=preview.sample,scalar=column=>/^(VARCHAR2|NVARCHAR2|CHAR|NCHAR|NUMBER|FLOAT|BINARY_FLOAT|BINARY_DOUBLE|DATE|TIMESTAMP.*)$/.test(column[2]),isSampleable=['TABLE','VIEW','MATERIALIZED VIEW'].includes(preview.kind);return `<div class="catalog-object-preview"><div class="catalog-preview-heading"><div><b>${realEscape(preview.schema)}.${realEscape(preview.name)}</b><span>${realEscape(preview.kind)} · ${columns.length} columns · metadata only</span></div><button type="button" onclick="realSourceCloseObjectPreview()">Close</button></div><div class="catalog-preview-section-heading"><h4>Columns / structure</h4><div><button type="button" onclick="realSourceSetAllPreviewColumns(true)">Select all sample fields</button><button type="button" onclick="realSourceSetAllPreviewColumns(false)">Clear selection</button></div></div><div class="tablewrap"><table class="table"><thead><tr><th>Column</th><th>Type</th><th>Nullable</th><th>Sample field</th></tr></thead><tbody>${columns.map(c=>`<tr><td>${realEscape(c[0])}</td><td>${realEscape(c[2])}</td><td>${c[3]==='Y'?'Yes':'No'}</td><td>${scalar(c)?`<input type="checkbox" class="catalog-preview-column" value="${realEscape(c[0])}" aria-label="Preview ${realEscape(c[0])}">`:'Not available for preview'}</td></tr>`).join('')||'<tr><td colspan="4">No column metadata was returned.</td></tr>'}</tbody></table></div><h4>Primary / Foreign keys</h4><div class="tablewrap"><table class="table"><thead><tr><th>Constraint</th><th>Type</th><th>Column</th><th>Position</th><th>References</th></tr></thead><tbody>${keys.map(k=>{const fk=foreign.find(f=>f[0]===k[0]&&f[2]===k[2]&&f[4]===k[3]);return `<tr><td>${realEscape(k[0])}</td><td>${k[1]==='P'?'Primary key':k[1]==='R'?'Foreign key':realEscape(k[1])}</td><td>${realEscape(k[2])}</td><td>${realEscape(k[3])}</td><td>${fk?`${realEscape(fk[3])}.${realEscape(fk[4])}.${realEscape(fk[5])}`:'—'}</td></tr>`;}).join('')||'<tr><td colspan="5">No visible primary/foreign keys were returned.</td></tr>'}</tbody></table></div>${isSampleable?`<div class="catalog-sample-controls"><label>Example rows (1–5)<input id="catalog-preview-rows" type="number" min="1" max="5" value="5"></label><label><input id="catalog-preview-budget-ack" type="checkbox"> I confirm these selected columns and the bounded source query</label><button type="button" onclick="realSourceReadObjectPreview()" ${preview.sampleLoading||realSourceUI.busy?'disabled':''}>${preview.sampleLoading?'Reading…':'Read example values (max 5 rows)'}</button><small>Only checked scalar columns are queried. LOBs are excluded. A row limit does not guarantee physical I/O.</small></div>${sample?`<h4>Example values · ${sample.sample_count} rows · not saved</h4><div class="tablewrap"><table class="table"><thead><tr>${sample.columns.map(c=>`<th>${realEscape(c)}</th>`).join('')}</tr></thead><tbody>${sample.rows.map(row=>`<tr>${row.map(value=>`<td>${realEscape(value)}</td>`).join('')}</tr>`).join('')||'<tr><td colspan="20">The query returned no rows.</td></tr>'}</tbody></table></div>`:''}${preview.sampleError?`<div class="callout">${realEscape(preview.sampleError)}</div>`:''}`:'<div class="callout">Example row preview is available for Tables and Views.</div>'}<small>${realEscape(metadata?.limitations||'Metadata visible to the current Oracle account only.')}</small></div>`;}
async function realSourceWaitForJob(action,data){const receipt=await realApi(action,{...data,profile_id:realSourceUI.profileId});let job;do{await new Promise(resolve=>setTimeout(resolve,300));job=await realApi('jobs/'+receipt.job_id);}while(job.state==='running');if(job.state==='failed')throw new Error(job.error||`${action} failed`);if(job.state!=='read_completed')throw new Error('The source operation did not complete.');return job;}
async function realSourceWaitForProfileJob(profileId,action,data){const receipt=await realApi(action,{...data,profile_id:profileId});let job;do{await new Promise(resolve=>setTimeout(resolve,300));job=await realApi('jobs/'+receipt.job_id);}while(job.state==='running');if(job.state==='failed')throw new Error(job.error||`${action} failed`);if(job.state!=='read_completed')throw new Error('The source operation did not complete.');return job;}
