function realSourceRenderCatalog(){const host=document.querySelector('.source-manager-drawer #real-source-manager-mount>.real-source-inline'),scroll=host?.scrollTop||0,node=document.querySelector('#real-source-discovery .catalog-filter-panel');if(node){node.outerHTML=realSourceCatalogMarkup();realSourcePlaceAutoSelect(document.querySelector('#real-source-discovery .catalog-filter-panel'));}if(host)host.scrollTop=scroll;}
function realSourceSetSchemaChecked(input){const scroll=document.querySelector('#real-source-discovery .schema-options')?.scrollTop||0,selected=new Set(realSourceUI.catalogSelectedSchemas);if(input.checked)selected.add(input.value);else selected.delete(input.value);realSourceUI.catalogSelectedSchemas=[...selected];realSourceUI.catalogVisiblePage=1;realSourcePersistCatalogProfile();realSourceRenderCatalog();const list=document.querySelector('#real-source-discovery .schema-options');if(list)list.scrollTop=scroll;}
function realSourceSelectAllSchemas(){realSourceUI.catalogSelectedSchemas=[];realSourceUI.catalogSchemaSearch='';realSourceUI.catalogVisiblePage=1;realSourcePersistCatalogProfile();realSourceRenderCatalog();}
function realSourceSetVisibleCatalogPage(page){const pages=Math.max(1,Math.ceil(realSourceFilteredCatalog().length/realSourceUI.catalogPageSize));realSourceUI.catalogVisiblePage=Math.max(1,Math.min(pages,page));realSourceRenderCatalog();}
function realSourceSetCatalogPageSize(value){if(![50,100].includes(value))return;realSourceUI.catalogPageSize=value;realSourceUI.catalogVisiblePage=1;realSourceRenderCatalog();}
function realSourceToggleCatalogObject(input){const {schema,object,kind}=input.dataset;if(!schema||!object||!kind)return;const selected=realSourceUI.catalogSelectedObjects;const index=selected.findIndex(s=>s.schema===schema&&s.name===object&&s.kind===kind);if(input.checked&&index<0)selected.push({schema,name:object,kind});else if(!input.checked&&index>=0)selected.splice(index,1);const active=input.checked?{schema,name:object,kind}:selected[selected.length-1]||null;invalidateDatasetRequest('Selected Oracle catalog object changed',realSourceUI.profileId);realSourceUI.schema=active?.schema||'';realSourceUI.table=active?.name||'';realSourceUI.objectType=active?.kind||'';realSourceUI.metadata=null;realSourceUI.sample=null;liveSourceDiscovery=null;liveSourceDraft=null;realSourcePersistCatalogProfile();realSourceSyncCatalogSelectionActions();const results=document.getElementById('real-source-discovery-results');if(results)results.replaceChildren();}
function realSourceClearCatalogSelection(){if(realSourceUI.busy)return;invalidateDatasetRequest('All Oracle catalog object selections cleared',realSourceUI.profileId);realSourceUI.catalogSelectedObjects=[];realSourceUI.schema='';realSourceUI.table='';realSourceUI.objectType='';realSourceUI.metadata=null;realSourceUI.sample=null;realSourceUI.catalogPreview=null;realSourceUI.catalogAutoStatus='All Table/View selections cleared.';liveSourceDiscovery=null;liveSourceDraft=null;realSourcePersistCatalogProfile();document.querySelectorAll('.catalog-object-checkbox:checked').forEach(input=>{input.checked=false;});const status=document.getElementById('catalog-selection-status');if(status)status.textContent='No object checked.';const discover=document.getElementById('discover-checked-object');if(discover)discover.disabled=true;document.getElementById('real-source-discovery-results')?.replaceChildren();realSourceRenderCatalog();}
function realSourceDiscover(){if(!realSourceUI.profiles[realSourceUI.profileId]?.connected)return notify('Connect this Oracle profile before Discovery.');if(!realSourceUI.schema||!realSourceUI.table)return notify('Load the complete visible Table/View catalog, then select a schema/object first.');invalidateDatasetRequest('Oracle metadata is being rediscovered',realSourceUI.profileId);realSourceUI.metadata=null;realSourceUI.sample=null;liveSourceDiscovery=null;liveSourceDraft=null;document.getElementById('real-source-discovery-results')?.replaceChildren();realSourceRun('discover',{schema:realSourceUI.schema,table:realSourceUI.table,timeout:realSourceUI.config?.timeout||15});}
function realSourceSample(){if(!realSourceUI.profiles[realSourceUI.profileId]?.connected)return notify('Connect this Oracle profile before Sample.');const columns=[...document.querySelectorAll('.real-sample-column:checked')].map(x=>x.value),sample_rows=Number(document.getElementById('real-sample-rows').value),batch_size=Number(document.getElementById('real-batch-size').value),budget_ack=document.getElementById('real-budget-ack').checked;realSourceRun('sample',{schema:realSourceUI.schema,table:realSourceUI.table,timeout:realSourceUI.config?.timeout||15,sample_rows,batch_size,columns,budget_ack});}
function realSourceUseMetadata(){if(!liveSourceDiscovery)return;S.page='mapping';S.notice=`Real Source metadata ${liveSourceDiscovery.schema}.${liveSourceDiscovery.table} available for draft review; no sample values or credentials transferred.`;render();}
async function realSourceLogout(){try{await realApi('logout',{});}catch{}for(const c of P.connections.filter(x=>isOracleProfile(x))){c.status='disconnected';c.message='';window.dropRealSourceSnapshots?.(c.id);}persist();realSourceUI.csrf='';realSourceUI.session=false;realSourceUI.tested=false;realSourceUI.profiles={};realSourceResetCatalog();realSourceUI.schema='';realSourceUI.table='';realSourceUI.objectType='';realSourceUI.metadata=null;realSourceUI.sample=null;realSourceUI.connection=null;realSourceUI.config=null;realSourceUI.profileId=null;realSourceUI.promptProfileId=null;realSourceUI.expandedProfileId=null;liveSourceDiscovery=null;liveSourceDraft=null;realSourceUI.notice='Signed out. All Oracle profiles disconnected and in-memory credentials cleared.';render();}
function realSourceInstall(main){const banner=document.getElementById('runtime-banner');if(banner&&location.protocol==='https:')banner.textContent='Secure local mode · Oracle Source is protected from writes. Analytics Target publishing/ETL is not implemented yet.';main.querySelectorAll('.real-source-mount').forEach(mount=>mount.remove());if(S.drawer==='source-manager'){const profile=P.connections.find(c=>c.id===realSourceUI.expandedProfileId);const mount=document.getElementById('real-source-manager-mount');if(profile&&mount){mount.innerHTML=realSourcePanel(profile);realSourcePlaceAutoSelect(mount.querySelector('.catalog-filter-panel'));}}}
